/// FAST translations.
///
/// Usage: `context.read<FASTProvider>().tr('welcome')` or via the
/// `AppStrings.of(lang, key)` helper. Missing keys fall back to
/// English, then French.
///
/// Coverage: full for fr/en/tr/ar/es/pt/it/zh; essential keys for
/// hi/bn/ur/bm/wo/ln (rest fall back to English).
class AppStrings {
  /// Currently selected language — synced by FASTProvider so code
  /// without a BuildContext (providers, API layer, enums) can translate.
  static String currentLanguage = 'fr';

  /// Translate [key] using [currentLanguage].
  static String trNow(String key) => of(currentLanguage, key);

  /// (code, display name) — languages offered at signup and in settings.
  static const List<(String, String)> languages = [
    ('fr', '🇫🇷  Français'),
    ('en', '🇬🇧  English'),
    ('tr', '🇹🇷  Türkçe'),
    ('ar', '🇸🇦  العربية'),
    ('hi', '🇮🇳  हिन्दी'),
    ('bn', '🇧🇩  বাংলা'),
    ('ur', '🇵🇰  اردو'),
    ('bm', '🇲🇱  Bambara'),
    ('wo', '🇸🇳  Wolof'),
    ('ln', '🇨🇩  Lingala'),
    ('es', '🇪🇸  Español'),
    ('pt', '🇵🇹  Português'),
    ('it', '🇮🇹  Italiano'),
    ('zh', '🇨🇳  中文'),
  ];

  static const Map<String, Map<String, String>> _all = {
    'fr': _fr,
    'en': _en,
    'tr': _tr,
    'ar': _ar,
    'es': _es,
    'pt': _pt,
    'it': _it,
    'zh': _zh,
    'hi': _hi,
    'bn': _bn,
    'ur': _ur,
    'bm': _bm,
    'wo': _wo,
    'ln': _ln,
  };

  static String of(String lang, String key) =>
      _all[lang]?[key] ?? _all['en']?[key] ?? _fr[key] ?? key;

